// Bare public hostnames, one per line (commas/semicolons also accepted).
// Fail before any HTTP request rather than silently truncate the inventory.
const value = $input.first().json.domains;
if (typeof value !== 'string' || value.length > 8000) {
  throw new Error('Set domains to a text list of 1-5 bare domain names (max 8000 characters).');
}
const domains = [];
for (const part of value.split(/[\n,;]+/)) {
  const host = part.trim().toLowerCase().replace(/^www\./, '');
  if (!host) continue;
  const labels = host.split('.');
  if (host.length > 253 || labels.length < 2 ||
      !labels.every(s => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(s)) ||
      !/[a-z]/.test(labels[labels.length - 1])) {
    throw new Error('Use bare domain names only, without URLs, paths, ports or spreadsheet formulas.');
  }
  if (!domains.includes(host)) domains.push(host);
}
if (domains.length < 1 || domains.length > 5) {
  throw new Error('Configure 1-5 unique domains. Split a longer inventory into separate runs.');
}
return domains.map(domain => ({ json: { domain } }));

// One output row per requested domain, in input order, never a leaderboard.
// Partial API readings expose MISSING engines, not the other engines' verdicts.
const inputs = $input.all();
const requested = $('Prepare domains').all();
if (inputs.length !== requested.length) {
  throw new Error('Response count differs from domain count; refusing to mislabel CSV rows.');
}
const engines = ['ChatGPT', 'Claude', 'Gemini', 'Perplexity'];
const lookupAt = new Date().toISOString();
const safeList = xs => Array.isArray(xs) && new Set(xs).size === xs.length &&
  xs.every(x => engines.includes(x));
return inputs.map((item, index) => {
  // Use n8n item linking, including error items, rather than assuming body order.
  const domain = $('Prepare domains').itemMatching(index).json.domain;
  if (!requested.some(x => x.json.domain === domain)) throw new Error('Unlinked domain response.');
  const res = item.json;
  const httpStatus = Number(res.statusCode);
  const row = {
    domain,
    reading_state: 'request_failed',
    http_status: Number.isInteger(httpStatus) && httpStatus >= 100 && httpStatus <= 599 ? httpStatus : '',
    visibility_score: '',
    ChatGPT: 'unavailable', Claude: 'unavailable', Gemini: 'unavailable', Perplexity: 'unavailable',
    measurement_checked_at: '',
    lookup_at: lookupAt,
    notes: 'Request failed; no citation verdict. No automatic retry.',
    report_url: 'https://trirankai.com/site/' + domain,
    setup_url: 'https://trirankai.com/audit',
  };
  if (httpStatus === 429) {
    row.reading_state = 'rate_limited';
    row.notes = 'Read allowance reached. Try after the daily reset at 00:00 UTC. No citation verdict.';
    return { json: row };
  }
  if (httpStatus !== 200) return { json: row };
  const body = res.body;
  const c = body && typeof body === 'object' && body.domain === domain ? body.citation : null;
  row.reading_state = 'invalid_response';
  row.notes = 'Response did not match the domain or citation contract; no verdict inferred.';
  if (!c || typeof c !== 'object') return { json: row };
  if (c.state === 'scored' && safeList(c.cited) &&
      typeof c.score === 'number' && Number.isFinite(c.score) && c.score >= 0 && c.score <= 100 &&
      (c.cited.length === 0) === (c.score === 0) &&
      typeof c.checkedAt === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(c.checkedAt) &&
      Number.isFinite(Date.parse(c.checkedAt))) {
    const ageMs = Date.parse(lookupAt) - Date.parse(c.checkedAt);
    if (ageMs < -60000 || ageMs > 14 * 86400000) {
      row.reading_state = 'no_fresh_measurement';
      row.notes = 'Measurement timestamp is stale or in the future; no current score or verdict exported.';
    } else {
      row.reading_state = 'scored';
      row.visibility_score = c.score;
      row.measurement_checked_at = new Date(c.checkedAt).toISOString();
      for (const engine of engines) row[engine] = c.cited.includes(engine) ? 'cited' : 'not_cited';
      row.notes = 'Complete cached quartet. Domain prompts/times may differ; do not treat this inventory as a controlled competitor ranking.';
    }
  } else if (c.state === 'partial' && safeList(c.missing) && c.missing.length > 0 && c.missing.length < 4) {
    row.reading_state = 'partial';
    for (const engine of engines) row[engine] = c.missing.includes(engine) ? 'not_freshly_measured' : 'verdict_not_exposed';
    row.notes = 'Partial coverage. API names missing engines but does not expose the others\' verdicts or a complete score.';
  } else if (c.state === 'none') {
    row.reading_state = 'no_fresh_measurement';
    row.notes = 'No fresh citation reading available. This is not zero citations. A human can seed or refresh an audit at the setup URL.';
  }
  if (body.authError === 'invalid_key') row.notes += ' Optional API key rejected; API used anonymous access.';
  // Only validated hosts/dates/enums and our own prose reach CSV cells. Raw
  // response/error text (which could contain formulas or credentials) is not copied.
  return { json: row };
});
